# /etc/nginx/conf.d/api.conf
upstream api_backend {
    least_conn;                               # 最少连接算法
    server 10.0.1.11:8080 weight=2 max_fails=3 fail_timeout=10s;
    server 10.0.1.12:8080 max_fails=3 fail_timeout=10s;
    server 10.0.1.13:8080 backup;             # 其他都不可用时才启用
    keepalive 32;                             # 与后端保持的空闲长连接数
}

server {
    listen 80;
    location / {
        proxy_pass http://api_backend;
        proxy_http_version 1.1;               # 后端长连接需要 HTTP/1.1
        proxy_set_header Connection "";
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        # 连接失败、超时或 502/503 时换下一台重试（注意非幂等请求）
        proxy_next_upstream error timeout http_502 http_503;
    }
}
# 开源版只有被动健康检查（max_fails）；主动 health_check 属于 NGINX Plus

server {
    listen 443 ssl;
    server_name app.example.com;
    ssl_certificate     /etc/ssl/app/fullchain.pem;
    ssl_certificate_key /etc/ssl/app/privkey.pem;
    client_max_body_size 20m;                    # 上传大小上限

    location /api/ {
        proxy_pass http://127.0.0.1:3000;        # 转发给本机 Node 服务
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 60s;
    }

    location /api/stream {                      # SSE/AI 流式输出
        proxy_pass http://127.0.0.1:3000;
        proxy_buffering off;                     # 关闭缓冲，逐块下发
        proxy_read_timeout 1h;
    }

    location /ws {                               # WebSocket 升级
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}

const http = require('node:http');

// 服务端：空闲超时要大于前面负载均衡的空闲超时（AWS ALB 默认 60 秒）
// 否则后端先关连接，均衡器复用到已关闭的连接会返回 502
const server = http.createServer((req, res) => res.end('ok'));
server.keepAliveTimeout = 65_000;  // Node 默认值为 5 秒
server.headersTimeout = 66_000;    // 旧版 Node 中需大于 keepAliveTimeout
server.listen(3000);

// 客户端：显式启用连接复用并限制每个主机的并发连接
const agent = new http.Agent({ keepAlive: true, maxSockets: 50 });

function ping() {
  http.get({ host: 'localhost', port: 3000, path: '/', agent }, (res) => {
    res.resume();  // 必须读完响应体，连接才会被放回池中复用
  });
}
ping(); ping(); // 第二次请求复用第一次的连接

