// 服务端（Express）：有新消息立即返回，否则最多挂起 25 秒
const messages = [];           // 示例用内存，生产用数据库或 Redis
const waiters = new Set();

app.get('/poll', (req, res) => {
  const since = Number(req.query.since ?? 0);
  const fresh = messages.filter((m) => m.id > since);
  if (fresh.length) return res.json(fresh);

  const done = (msg) => { clearTimeout(timer); waiters.delete(done); res.json([msg]); };
  const timer = setTimeout(() => { waiters.delete(done); res.status(204).end(); }, 25_000);
  waiters.add(done);
  req.on('close', () => { clearTimeout(timer); waiters.delete(done); });
});

function publish(text) {
  const msg = { id: messages.length + 1, text };
  messages.push(msg);
  for (const w of [...waiters]) w(msg);
}

// 客户端：收到响应立刻发下一轮，出错时等待后重试
async function poll(since = 0) {
  for (;;) {
    try {
      const r = await fetch(`/poll?since=${since}`);
      if (r.status === 200) { const msgs = await r.json(); since = msgs.at(-1).id; render(msgs); }
    } catch { await new Promise((ok) => setTimeout(ok, 2000)); }
  }
}

# greeter.proto:
#   service Greeter { rpc SayHello (HelloRequest) returns (HelloReply); }
#   message HelloRequest { string name = 1; }
#   message HelloReply   { string message = 1; }
# 生成代码：pip install grpcio grpcio-tools
#   python -m grpc_tools.protoc -I. --python_out=. --grpc_python_out=. greeter.proto
import grpc
import greeter_pb2, greeter_pb2_grpc

with grpc.insecure_channel("localhost:50051") as channel:   # 内网示例，生产用 TLS
    stub = greeter_pb2_grpc.GreeterStub(channel)
    try:
        reply = stub.SayHello(
            greeter_pb2.HelloRequest(name="Q1f730"),
            timeout=2.0,                                  # 必须设截止时间
            metadata=[("x-request-id", "req-123")],
        )
        print(reply.message)
    except grpc.RpcError as e:
        if e.code() == grpc.StatusCode.DEADLINE_EXCEEDED:
            print("超时")
        elif e.code() == grpc.StatusCode.UNAVAILABLE:
            print("服务不可用，可按策略重试")
        else:
            raise

// user.proto
syntax = "proto3";
package demo.v1;

message User {
  int64  id    = 1;              // 1–15 号字段的标签只占 1 字节，留给高频字段
  string name  = 2;
  optional string nickname = 3;  // optional 可区分“未设置”与空字符串
  repeated string tags = 4;
  Status status = 5;
  reserved 6;                    // 已删除字段的编号，永不复用
  reserved "email";              // 也保留旧字段名
}

enum Status {
  STATUS_UNSPECIFIED = 0;        // proto3 枚举第一个值必须是 0，作为默认值
  STATUS_ACTIVE = 1;
  STATUS_BANNED = 2;
}

// 编码示例：字段 1 为 varint 150 → 字节 08 96 01
