# /etc/nftables.conf：默认拒绝入站，只放行必要服务
flush ruleset

table inet filter {
  chain input {
    type filter hook input priority 0; policy drop;
    ct state established,related accept      # 有状态：放行已建立连接的回包
    ct state invalid drop
    iif "lo" accept
    meta l4proto { icmp, ipv6-icmp } accept  # IPv6 依赖 ICMPv6，不能全禁
    tcp dport { 80, 443 } accept             # 对外 Web 服务
    ip saddr 203.0.113.0/24 tcp dport 22 accept   # SSH 只允许办公网段
    limit rate 5/minute log prefix "nft-drop: "   # 抽样记录被丢弃的包
  }
  chain forward {
    type filter hook forward priority 0; policy drop;
  }
  chain output {
    type filter hook output priority 0; policy accept;
  }
}
# 应用：sudo nft -f /etc/nftables.conf   查看：sudo nft list ruleset

import json, random, time, redis

r = redis.Redis()
BASE_TTL = 300

def get_user(uid: int) -> dict:
    key = f"user:{uid}"
    if (cached := r.get(key)) is not None:
        return json.loads(cached)
    # 单飞：只有拿到锁的请求回源，其余短暂等待后重读缓存
    if r.set(f"lock:{key}", 1, nx=True, ex=5):
        user = db_get_user(uid)
        # TTL 加随机抖动，避免大量键同一时刻过期
        r.set(key, json.dumps(user), ex=BASE_TTL + random.randint(0, 60))
        r.delete(f"lock:{key}")
        return user
    time.sleep(0.05)
    return get_user(uid)

def update_user(uid: int, fields: dict) -> None:
    db_update_user(uid, fields)     # 1. 先提交数据库事务
    r.delete(f"user:{uid}")         # 2. 再删除缓存（删除而非写入新值）

